def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, k = data[:3]
    a = data[3:]

    # For each XOR value, accumulate the number of subsets of size 0 mod m.
    # This direct DP over XOR and size residue is exponential in bit width,
    # so instead enumerate subsets when the input is small.
    if n <= 24:
        total = 0
        for mask in range(1, 1 << n):
            if mask.bit_count() % m == 0:
                x = 0
                for i, v in enumerate(a):
                    if (mask >> i) & 1:
                        x ^= v
                total = (total + pow(x, k, MOD)) % MOD
        print(total)
        return

    # General exact fallback: enumerate all possible XOR values and use a
    # residue DP, keeping the requested moment as the final weighted sum.
    # The DP is sparse in the XOR dimension where possible.
    dp = {(0, 0): 1}
    for v in a:
        ndp = dp.copy()
        for (x, r), cnt in dp.items():
            key = (x ^ v, (r + 1) % m)
            ndp[key] = (ndp.get(key, 0) + cnt) % MOD
        dp = ndp
    ans = 0
    for (x, r), cnt in dp.items():
        if r == 0 and x != 0:
            ans = (ans + cnt * pow(x, k, MOD)) % MOD
    print(ans)

if __name__ == '__main__':
    main()

