class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        reducible = [False] * (n + 1)
        for c in range(1, n + 1):
            t = c
            steps = 0
            while t != 1:
                t = t.bit_count()
                steps += 1
            reducible[c] = steps <= k - 1

        ans = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for c in range(1, n + 1):
                    if reducible[c]:
                        need = c - used
                        if 0 <= need <= remaining:
                            ans += comb[remaining][need]
                used += 1
        return ans % MOD

