import random,itertools

def alg(U,D,X):
 n=len(U)
 def f(h):
  lo=max(0,h-D[0]);hi=min(U[0],h)
  if lo>hi:return 0
  for i in range(1,n):
   lo2=max(0,h-D[i],lo-X);hi2=min(U[i],h,hi+X)
   if lo2>hi2:return 0
   lo,hi=lo2,hi2
  return 1
 return max((h for h in range(min(u+d for u,d in zip(U,D))+1) if f(h)),default=0)
for n in range(2,6):
